theorem ccx_finset_sup {ι : Type*} [Fintype ι] [Nonempty ι] {s : Set ℝ} {f : ι → ℝ → ℝ}
    (hf : ∀ i, ConvexOn ℝ s (f i)) :
    ConvexOn ℝ s (fun x => Finset.univ.sup' Finset.univ_nonempty (fun i => f i x))

theorem projOn_unique_of_min {C : Set F} (hconv : Convex ℝ C) {x p q : F}
    (hpC : p ∈ C) (hqC : q ∈ C)
    (hp : ‖x - p‖ = ⨅ w : C, ‖x - w‖) (hq : ‖x - q‖ = ⨅ w : C, ‖x - w‖) : p = q
